#include <vector>

struct Point {
    int x;
    int y;
};

int area(const Point& a, const Point& b) {
    return (b.x - a.x) * (b.y - a.y);
}

bool inside(const Point& p, int limit) {
    if (p.x < 0 || p.y < 0) {
        return false;
    }
    return p.x <= limit && p.y <= limit;
}

int count_positive(const std::vector<int>& values) {
    int count = 0;
    for (int value : values) {
        count += value > 0 ? 1 : 0;
    }
    return count;
}

